import React from "react";
import { NavLink } from "react-router-dom";

function Footer() {
  const year = new Date().getFullYear();

  return (
    <footer style={{ backgroundColor: "#2b1a00", color: "#fde8c0" }}>
      <div className="container py-5">
        <div className="row gy-4">

          {/* Brand Column */}
          <div className="col-lg-4 col-md-6">
            <h5 style={{ fontFamily: "'Playfair Display', serif", color: "#f5a623" }}>
              🍯 GoldenHive
            </h5>
            <p className="small mt-2" style={{ color: "#e8cfa0", lineHeight: 1.8 }}>
              Pure, raw, and ethically sourced honey — straight from our hives to
              your table. Nature's sweetest gift, delivered with love.
            </p>
            {/* Social Icons */}
            <div className="d-flex gap-3 mt-3">
              {["facebook", "instagram", "twitter"].map((social) => (
                <a
                  key={social}
                  href={`https://${social}.com`}
                  target="_blank"
                  rel="noreferrer"
                  style={{ color: "#f5a623", fontSize: "1.2rem" }}
                  aria-label={social}
                >
                  <i className={`bi bi-${social}`} />
                </a>
              ))}
            </div>
          </div>

          {/* Quick Links */}
          <div className="col-lg-2 col-md-6 col-6">
            <h6 className="text-uppercase mb-3" style={{ color: "#f5a623", letterSpacing: "0.1em", fontSize: "0.8rem" }}>
              Quick Links
            </h6>
            <ul className="list-unstyled mb-0">
              {[
                { to: "/",         label: "Home"     },
                { to: "/about",    label: "About Us" },
                { to: "/products", label: "Products" },
                { to: "/contact",  label: "Contact"  },
              ].map(({ to, label }) => (
                <li key={to} className="mb-2">
                  <NavLink
                    to={to}
                    style={{ color: "#e8cfa0", fontSize: "0.9rem", textDecoration: "none" }}
                    onMouseOver={(e) => (e.target.style.color = "#f5a623")}
                    onMouseOut={(e)  => (e.target.style.color = "#e8cfa0")}
                  >
                    {label}
                  </NavLink>
                </li>
              ))}
            </ul>
          </div>

          {/* Products */}
          <div className="col-lg-2 col-md-6 col-6">
            <h6 className="text-uppercase mb-3" style={{ color: "#f5a623", letterSpacing: "0.1em", fontSize: "0.8rem" }}>
              Our Honey
            </h6>
            <ul className="list-unstyled mb-0">
              {["Raw Wildflower", "Manuka", "Clover", "Infused Blends", "Gift Sets"].map((item) => (
                <li key={item} className="mb-2">
                  <span style={{ color: "#e8cfa0", fontSize: "0.9rem", cursor: "default" }}>
                    {item}
                  </span>
                </li>
              ))}
            </ul>
          </div>

          {/* Contact */}
          <div className="col-lg-4 col-md-6">
            <h6 className="text-uppercase mb-3" style={{ color: "#f5a623", letterSpacing: "0.1em", fontSize: "0.8rem" }}>
              Get in Touch
            </h6>
            <ul className="list-unstyled mb-0" style={{ color: "#e8cfa0", fontSize: "0.9rem" }}>
              <li className="mb-2">📍 12 Meadow Lane, Beekeeper Valley, CA</li>
              <li className="mb-2">📞 +1 (800) 555-HIVE</li>
              <li className="mb-2">✉️ hello@goldenhive.com</li>
            </ul>
          </div>

        </div>

        {/* Divider */}
        <hr style={{ borderColor: "rgba(245,166,35,0.25)", marginTop: "2.5rem" }} />

        {/* Bottom Bar */}
        <div className="d-flex flex-column flex-sm-row justify-content-between align-items-center gap-2">
          <p className="mb-0 small" style={{ color: "#b5956a" }}>
            © {year} GoldenHive. All rights reserved.
          </p>
          <p className="mb-0 small" style={{ color: "#b5956a" }}>
            Made with 🍯 &amp; ❤️ for honey lovers
          </p>
        </div>
      </div>
    </footer>
  );
}

export default Footer;
